// Conditions

/** urn:corpus:subscriptions:subscription:operation:change_plan — ensures: input.proration != 'at_period_end' or output.scheduled_plan_id is present and output.scheduled_plan_id = input.plan_id */
export const SubscriptionChangePlanEnsures1 = (p: { input: SubscriptionChangePlanRequest; current: SubscriptionSubscription; output: SubscriptionSubscription }): boolean =>
  ((p.input.proration as string) !== "at_period_end" || (p.output.scheduled_plan_id !== undefined && (p.output.scheduled_plan_id as string) === (p.input.plan_id as string)));

/** urn:corpus:subscriptions:subscription:operation:create_subscription — ensures: input.trial_days is present and input.trial_days > 0 or input.trial_end is present or output.status = 'active' */
export const SubscriptionCreateSubscriptionEnsures1 = (p: { input: SubscriptionCreateRequest; output: SubscriptionSubscription }): boolean =>
  (((p.input.trial_days !== undefined && (p.input.trial_days as number) > 0) || p.input.trial_end !== undefined) || (p.output.status as string) === "active");

/** urn:corpus:subscriptions:subscription:operation:create_subscription — ensures: input.trial_days is absent or input.trial_days = 0 or output.status = 'trialing' */
export const SubscriptionCreateSubscriptionEnsures2 = (p: { input: SubscriptionCreateRequest; output: SubscriptionSubscription }): boolean =>
  ((p.input.trial_days === undefined || (p.input.trial_days as number) === 0) || (p.output.status as string) === "trialing");

/** urn:corpus:subscriptions:subscription:operation:create_subscription — ensures: input.trial_end is absent or output.status = 'trialing' */
export const SubscriptionCreateSubscriptionEnsures3 = (p: { input: SubscriptionCreateRequest; output: SubscriptionSubscription }): boolean =>
  (p.input.trial_end === undefined || (p.output.status as string) === "trialing");
